    .split('\n').filter((f) => /\.(mjs|js|md)$/.test(f));
} catch { process.exit(0); }

const miss = [];
for (const rel of files) {
  const abs = join(root, rel);
  if (!existsSync(abs)) continue;
  const text = readFileSync(abs, 'utf8');
  // Literal specifiers, and template specifiers whose prefix is a const in the same file.
  const consts = new Map([...text.matchAll(/const\s+([A-Z_][A-Z0-9_]*)\s*=\s*["'`]([^"'`]+)["'`]/g)].map((m) => [m[1], m[2]]));
  const specs = [...text.matchAll(/["'`]([^"'`]*shared\/packs\/claudinite-tasks\/[^"'`]*)["'`]/g)].map((m) => m[1]);
  const tmpl = [...text.matchAll(/`\$\{([A-Za-z_][A-Za-z0-9_]*)\}(\/[^"'`]+)`/g)]
    .map((m) => (consts.has(m[1]) ? consts.get(m[1]) + m[2] : null)).filter(Boolean)
    .filter((s) => s.includes('claudinite-tasks'));
  for (const s of [...specs, ...tmpl]) {
    if (!/\.(mjs|js|json|md)$/.test(s)) continue;
    const target = resolve(dirname(abs), s);
    if (!existsSync(target) || !statSync(target).isFile()) miss.push(`${rel} -> ${s}`);
  }
}
if (miss.length) { console.log(miss.join('\n')); process.exit(1); }
